using IptvManagement.Domain.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace IptvManagement.Infrastructure.Data;
public class CustomerConfiguration:IEntityTypeConfiguration<Customer>{ public void Configure(EntityTypeBuilder<Customer> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.CustomerNumber).IsUnique(); e.HasIndex(x=>x.Email); e.Property(x=>x.CustomerNumber).HasMaxLength(40); e.Property(x=>x.Email).HasMaxLength(256); e.Property(x=>x.FirstName).HasMaxLength(100); e.Property(x=>x.LastName).HasMaxLength(100); }}
public class SubscriptionConfiguration:IEntityTypeConfiguration<Subscription>{ public void Configure(EntityTypeBuilder<Subscription> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.SubscriptionNumber).IsUnique(); e.HasIndex(x=>x.PlaylistTokenHash).IsUnique().HasFilter("[PlaylistTokenHash] IS NOT NULL"); e.Property(x=>x.SubscriptionNumber).HasMaxLength(40); e.HasOne(x=>x.Customer).WithMany(x=>x.Subscriptions).HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.Restrict); e.HasOne(x=>x.Package).WithMany().HasForeignKey(x=>x.PackageId).OnDelete(DeleteBehavior.Restrict); }}
public class PackageConfiguration:IEntityTypeConfiguration<SubscriptionPackage>{ public void Configure(EntityTypeBuilder<SubscriptionPackage> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.Name).IsUnique(); e.Property(x=>x.Name).HasMaxLength(120); e.Property(x=>x.Price).HasPrecision(18,2); e.Property(x=>x.Currency).HasMaxLength(3); }}
public class DeviceConfiguration:IEntityTypeConfiguration<Device>{ public void Configure(EntityTypeBuilder<Device> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>new{x.SubscriptionId,x.DeviceIdentifierHash}).IsUnique(); e.Property(x=>x.DeviceName).HasMaxLength(120); e.Property(x=>x.DeviceIdentifierHash).HasMaxLength(128); e.HasOne(x=>x.Customer).WithMany(x=>x.Devices).HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.Restrict); e.HasOne(x=>x.Subscription).WithMany(x=>x.Devices).HasForeignKey(x=>x.SubscriptionId).OnDelete(DeleteBehavior.Restrict); }}
public class ChannelConfiguration:IEntityTypeConfiguration<Channel>{ public void Configure(EntityTypeBuilder<Channel> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>new{x.CategoryId,x.Name}).IsUnique(); e.Property(x=>x.Name).HasMaxLength(160); e.Property(x=>x.StreamUrlEncrypted).HasMaxLength(4096); e.Property(x=>x.LicenseReference).HasMaxLength(300); e.HasOne(x=>x.Category).WithMany(x=>x.Channels).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict); }}
public class CategoryConfiguration:IEntityTypeConfiguration<ChannelCategory>{ public void Configure(EntityTypeBuilder<ChannelCategory> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.Name).IsUnique(); e.Property(x=>x.Name).HasMaxLength(120); }}
public class PackageChannelConfiguration:IEntityTypeConfiguration<PackageChannel>{ public void Configure(EntityTypeBuilder<PackageChannel> e){ e.HasKey(x=>new{x.PackageId,x.ChannelId}); e.HasOne(x=>x.Package).WithMany(x=>x.PackageChannels).HasForeignKey(x=>x.PackageId); e.HasOne(x=>x.Channel).WithMany(x=>x.PackageChannels).HasForeignKey(x=>x.ChannelId); }}
public class PaymentConfiguration:IEntityTypeConfiguration<Payment>{ public void Configure(EntityTypeBuilder<Payment> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.PaymentNumber).IsUnique(); e.Property(x=>x.Amount).HasPrecision(18,2); }}
public class InvoiceConfiguration:IEntityTypeConfiguration<Invoice>{ public void Configure(EntityTypeBuilder<Invoice> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.InvoiceNumber).IsUnique(); e.Property(x=>x.NetAmount).HasPrecision(18,2); e.Property(x=>x.TaxAmount).HasPrecision(18,2); e.Property(x=>x.GrossAmount).HasPrecision(18,2); }}
public class AuditLogConfiguration:IEntityTypeConfiguration<AuditLog>{ public void Configure(EntityTypeBuilder<AuditLog> e){ e.HasKey(x=>x.Id); e.Property(x=>x.Action).HasMaxLength(160); e.Property(x=>x.EntityName).HasMaxLength(160); }}
public class PlaylistAccessLogConfiguration:IEntityTypeConfiguration<PlaylistAccessLog>{ public void Configure(EntityTypeBuilder<PlaylistAccessLog> e){ e.HasKey(x=>x.Id); e.Property(x=>x.FailureReason).HasMaxLength(300); }}
public class SystemSettingConfiguration:IEntityTypeConfiguration<SystemSetting>{ public void Configure(EntityTypeBuilder<SystemSetting> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.Key).IsUnique(); e.Property(x=>x.Key).HasMaxLength(120); }}
public class DeviceActivationCodeConfiguration:IEntityTypeConfiguration<DeviceActivationCode>{ public void Configure(EntityTypeBuilder<DeviceActivationCode> e){ e.HasKey(x=>x.Id); e.HasIndex(x=>x.CodeHash).IsUnique(); }}
